def is_valid_ipv4(s: str) -> bool:
    """
    Given a string s, return True if s is a valid IPv4 address.
    An IPv4 address is valid if s can be parsed into four integers between 0 and 255,
    and there are no leading zeros in any of the integers.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if part == '0' and len(part) > 1:
            return False
        try:
            num = int(part)
            if num < 0 or num > 255:
                return False
        except ValueError:
            return False
    return True
```

